const KEY = 'veintisiete.data.v1';
const habitSeeds = [
  ['Pasos','Caminar 10.000 pasos','diaria'],
  ['Móvil','Dejar el móvil fuera del dormitorio al dormir','diaria'],
  ['Python','Aprender Python','diaria'],
  ['Matemáticas','Preparar matemáticas','diaria'],
  ['Lectura','Leer al menos 10 páginas','diaria'],
  ['Estirar','Estirar','diaria'],
  ['Entrenar','Entrenar','diaria'],
].map(([name,description])=>({id:id(),name,description,frequency:'daily',days:[],weeklyTarget:3,startDate:today(),paused:false,archived:false}));
const seedAreas = [
  {name:'Matemáticas — preparación personal',kind:'math',topics:['Álgebra','Funciones','Trigonometría','Logaritmos','Probabilidad','Estadística','Cálculo','Derivadas e integrales','Álgebra lineal','Matrices','Vectores']},
  {name:'Inglés — formación personal',kind:'english',topics:['Vocabulario','Gramática','Listening','Reading','Writing','Speaking','Conversación','Exámenes oficiales']},
  {name:'Python y programación',kind:'python',topics:['Fundamentos','Variables y tipos','Condicionales','Bucles','Funciones','Estructuras de datos','Ejercicios','Proyectos']},
].map(x=>({...x,id:id()}));
const facts = [
  {text:'Un día en Marte dura unas 24 horas y 39 minutos.',source:'NASA',url:'https://science.nasa.gov/mars/facts/'},
  {text:'El pulpo tiene tres corazones y su sangre contiene hemocianina.',source:'Smithsonian Ocean',url:'https://ocean.si.edu/ocean-life/invertebrates/octopus'},
  {text:'La Torre Eiffel puede crecer varios centímetros en los días calurosos por la expansión térmica del hierro.',source:'Eiffel Tower',url:'https://www.toureiffel.paris/en/news/history-and-culture/why-does-eiffel-tower-change-size'},
  {text:'Los tiburones existen desde antes que los árboles: sus primeros antepasados aparecieron hace más de 400 millones de años.',source:'Natural History Museum',url:'https://www.nhm.ac.uk/discover/shark-evolution-a-450-million-year-timeline.html'},
  {text:'Las abejas melíferas comunican la dirección y distancia de alimento mediante una danza.',source:'USDA Agricultural Research Service',url:'https://www.ars.usda.gov/oc/br/bee-research/'},
  {text:'La luz del Sol tarda alrededor de ocho minutos y veinte segundos en llegar a la Tierra.',source:'NASA',url:'https://science.nasa.gov/sun/facts/'},
  {text:'El agua puede existir en la naturaleza en estado sólido, líquido y gaseoso.',source:'USGS Water Science School',url:'https://www.usgs.gov/special-topics/water-science-school/science/water-cycle'},
];
const defaults = () => ({version:1,settings:{createdAt:today(),startDate:today(),installPromptDismissed:false},habits:habitSeeds,habitEntries:{},areas:seedAreas,sessions:[],subjects:[{id:id(),name:'Matemáticas'},{id:id(),name:'Inglés'}],grades:[],extras:[],extraCategories:['Cultura','Deporte','Cocina','Habilidad','Excursión','Otro'],moods:{},reflections:{},goals:[],favorites:[],customFacts:[]});
let state = load();
let view = 'today';
let focusDate = today();
let calendarMonth = new Date();
let statsRange = '30';
let statsCustom = {from:today(),to:today()};
let toastTimer;
const root = document.querySelector('#view-root');
const dialog = document.querySelector('#dialog');

function id(){return crypto.randomUUID ? crypto.randomUUID() : `${Date.now().toString(36)}${Math.random().toString(36).slice(2)}`}
function today(){const d=new Date();return dateKey(d)}
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseDate(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function load(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(!saved)return defaults();const d=defaults();return {...d,...saved,settings:{...d.settings,...saved.settings},habits:saved.habits||d.habits,areas:saved.areas||d.areas,subjects:saved.subjects||d.subjects,extraCategories:saved.extraCategories||d.extraCategories,habitEntries:saved.habitEntries||{},moods:saved.moods||{},reflections:saved.reflections||{}}}catch{return defaults()}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));document.querySelector('#save-status').textContent='Guardado en este dispositivo';}catch{document.querySelector('#save-status').textContent='No se pudo guardar';toast('No se pudo guardar. Exporta una copia de seguridad.')}}
function fmtDate(s,opts={weekday:'long',day:'numeric',month:'long'}){return parseDate(s).toLocaleDateString('es-ES',opts)}
function fmtShort(s){return parseDate(s).toLocaleDateString('es-ES',{day:'numeric',month:'short'})}
function thisWeekBounds(s=today()){const d=parseDate(s);const day=(d.getDay()+6)%7;const start=new Date(d);start.setDate(d.getDate()-day);const end=new Date(start);end.setDate(start.getDate()+6);return [dateKey(start),dateKey(end)]}
function daysBetween(a,b){return Math.round((parseDate(b)-parseDate(a))/86400000)}
function entryFor(date,habitId){return state.habitEntries[date]?.[habitId]||null}
function entryDetails(entry){if(!entry)return {};const {status,updatedAt,...details}=entry;return details}
function setEntry(date,habitId,status,details={}){state.habitEntries[date]??={};if(status==='pending'&&!Object.keys(details).length){delete state.habitEntries[date][habitId]}else state.habitEntries[date][habitId]={status,...details,updatedAt:new Date().toISOString()};if(!Object.keys(state.habitEntries[date]).length)delete state.habitEntries[date];save()}
function activeHabits(){return state.habits.filter(h=>!h.archived&&!h.paused&&h.startDate<=focusDate)}
function plannedForDay(date){return state.habits.filter(h=>!h.archived&&!h.paused&&h.startDate<=date&&(h.frequency==='daily'||(h.frequency==='specific'&&h.days.includes(parseDate(date).getDay()))))}
function scheduledToday(){return plannedForDay(focusDate)}
function ratioForDay(date){const plan=plannedForDay(date);const included=plan.filter(h=>entryFor(date,h.id)?.status!=='excluded');const done=included.filter(h=>entryFor(date,h.id)?.status==='done').length;return {done,total:included.length,excluded:plan.length-included.length,percent:included.length?Math.round(done/included.length*100):0}}
function weekDone(h){const [a,b]=thisWeekBounds();return Object.entries(state.habitEntries).reduce((n,[d,entries])=>n+(d>=a&&d<=b&&entries?.[h.id]?.status==='done'?1:0),0)}
function setView(next){view=next;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#sidebar').classList.remove('open');render()}
function showToast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function openDialog(title,content){document.querySelector('#dialog-content').innerHTML=`<h2>${title}</h2>${content}`;dialog.showModal()}
function closeDialog(){dialog.close()}
function field(label,name,value='',type='text',extra=''){return `<div class="form-field"><label for="f-${name}">${label}</label><input class="field" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value){return `<div class="form-field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function textArea(label,name,value='',placeholder=''){return `<div class="form-field wide"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`}
function dialogActions(cancel='Cancelar',submit='Guardar'){return `<div class="dialog-actions"><button class="btn line" type="button" data-action="close-dialog">${cancel}</button><button class="btn" type="submit">${submit}</button></div>`}
function pageHead(eyebrow,title,sub='',action=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${action}</div>`}
function section(title,sub='',action=''){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function empty(title,description,action=''){return `<div class="empty"><strong>${title}</strong>${description}${action?`<div class="actions-row" style="justify-content:center;margin-top:13px">${action}</div>`:''}</div>`}
function completedDot(){return '<span class="privacy-dot"></span>'}
function activityOn(date){return Boolean(state.habitEntries[date]||state.sessions.some(x=>x.date===date)||state.extras.some(x=>x.date===date)||state.grades.some(x=>x.date===date)||state.moods[date]||state.reflections[date]?.trim())}
function header(){document.querySelector('#today-date').textContent=new Date().toLocaleDateString('es-ES',{day:'numeric',month:'long',year:'numeric'});document.querySelector('#page-crumb').textContent=({today:'Hoy',calendar:'Calendario',habits:'Hábitos',learning:'Formación personal',academics:'Notas académicas',extras:'Extras y experiencias',goals:'Objetivos',statistics:'Estadísticas',settings:'Configuración'})[view]||'Hoy'}
function render(){header();const pages={today:renderToday,calendar:renderCalendar,habits:renderHabits,learning:renderLearning,academics:renderAcademics,extras:renderExtras,goals:renderGoals,statistics:renderStatistics,settings:renderSettings};root.innerHTML=(pages[view]||renderToday)();bindLocalForms()}
function renderToday(){const day=focusDate;const ratio=ratioForDay(day);const planned=scheduledToday();const completed=planned.filter(h=>entryFor(day,h.id)?.status==='done').length;const excluded=planned.filter(h=>entryFor(day,h.id)?.status==='excluded').length;const weekly=state.habits.filter(h=>!h.archived&&!h.paused&&h.frequency==='weekly'&&h.startDate<=day);const sessions=state.sessions.filter(s=>s.date===day);const extras=state.extras.filter(x=>x.date===day);const fact=facts[(parseDate(day).getTime()/86400000|0)%facts.length];const mood=state.moods[day]||0;const quote=fact;
return `${pageHead('DOMINGO A DOMINGO',day===today()?'Un día cada vez':`Tu día · ${fmtDate(day)}`,'Un espacio para avanzar con calma, en lo que hoy te apetezca.',`<div class="date-pill">${fmtDate(day,{day:'numeric',month:'long',year:'numeric'})}</div>`)}
<div class="grid two"><section class="card hero-card"><p class="eyebrow">${day===today()?'TU RITMO DE HOY':'RESUMEN DEL DÍA'}</p><h2>${completed===planned.length&&planned.length?'Lo has hecho a tu manera.':'Un paso pequeño también cuenta.'}</h2><p>${planned.length?`${completed} de ${Math.max(0,planned.length-excluded)} hábitos previstos completados${excluded?` · ${excluded} en descanso`:''}. Sin prisa: el día todavía es tuyo.`:'No hay hábitos previstos hoy. Puedes descansar o dedicarte a otra cosa.'}</p><div class="hero-progress"><strong>${ratio.percent}%</strong><span>${completed}/${ratio.total} hábitos</span></div></section><section class="card quote-card"><button class="quote-fav ${state.favorites.includes(quote.text)?'saved':''}" data-action="favorite-fact" title="Guardar curiosidad">${state.favorites.includes(quote.text)?'♥':'♡'}</button><span class="quote-type">✦ Curiosidad del día</span><h3>${esc(quote.text)}</h3><p>Fuente: <a href="${quote.url}" target="_blank" rel="noopener">${esc(quote.source)}</a></p><button class="link-button" style="margin-top:10px;padding-left:0" data-action="facts-history">Ver curiosidades anteriores y favoritas →</button></section></div>
<div class="grid three section"><div class="card metric"><span class="metric-icon">✓</span><span class="metric-label">HÁBITOS COMPLETADOS</span><strong>${completed}<small> / ${ratio.total}</small></strong><small>${excluded} excluidos · no cuentan como incumplidos</small></div><div class="card metric"><span class="metric-icon">⌘</span><span class="metric-label">SESIONES DE FORMACIÓN</span><strong>${sessions.length}</strong><small>${sessions.reduce((n,s)=>n+(Number(s.minutes)||0),0)} min registrados</small></div><div class="card metric"><span class="metric-icon">✳</span><span class="metric-label">EXPERIENCIAS</span><strong>${extras.length}</strong><small>Actividades puntuales, sin rachas</small></div></div>
<div class="grid two section"><section class="card">${section('Lo que te propusiste','Marca lo que hiciste; los detalles son opcionales.',`<button class="link-button" data-view="habits">Gestionar hábitos →</button>`)}${planned.length?`<div class="habit-list">${planned.map(h=>{const entry=entryFor(day,h.id);const done=entry?.status==='done',skip=entry?.status==='excluded';return `<div class="habit-row"><input class="check" type="checkbox" data-action="toggle-habit" data-id="${h.id}" ${done?'checked':''} aria-label="Marcar ${esc(h.name)}" ${skip?'disabled':''}><div><div class="habit-name">${esc(h.name)}</div><div class="habit-meta">${skip?'Día excluido':entry?.note?esc(entry.note):esc(h.description||'')}</div></div><div class="habit-right">${skip?'<span class="tag warn">Descanso</span>':''}<button class="link-button" data-action="habit-day-detail" data-id="${h.id}" data-date="${day}">${entry?.minutes?`${entry.minutes} min`:'Añadir detalle'}</button><button class="icon-button" data-action="exclude-habit" data-id="${h.id}" data-date="${day}" title="${skip?'Quitar descanso':'Excluir hoy'}">${skip?'↶':'−'}</button></div></div>`}).join('')}</div>`:empty('Hoy sin hábitos','No hay nada previsto. Tus extras y aprendizajes también tienen su espacio.')}</section><section class="card">${section('Un registro rápido','Ánimo y reflexión, solo si te apetece.')}<div class="mood-options">${['Muy mal','Mal','Normal','Bien','Muy bien'].map((m,i)=>`<button class="mood-option ${mood===i+1?'active':''}" data-action="mood" data-value="${i+1}"><span>${['☹️','🙁','😐','🙂','😊'][i]}</span>${m}</button>`).join('')}</div><div class="divider"></div><textarea data-autosave-reflection placeholder="Qué ha pasado, qué has aprendido o qué quieres recordar…" aria-label="Reflexión diaria"></textarea><p class="footer-note">Se guarda automáticamente en este dispositivo.</p></section></div>
${weekly.length?`<section class="card section">${section('Hábitos semanales','Cuenta sesiones de la semana; no ocupan un día concreto.')}${weekly.map(h=>{const n=weekDone(h),target=Number(h.weeklyTarget)||3;return `<div class="list-row"><div class="list-main"><strong>${esc(h.name)}</strong><small>${n} de ${target} veces esta semana</small><div class="progress-track" style="margin-top:8px;max-width:280px"><span style="width:${Math.min(100,n/target*100)}%"></span></div></div><button class="btn soft small" data-action="weekly-done" data-id="${h.id}" data-date="${day}">Registrar hoy</button></div>`}).join('')}</section>`:''}
<div class="grid two section"><section class="card">${section('Lo que aprendiste','Sesiones de formación registradas.',`<button class="link-button" data-action="new-session">Añadir →</button>`)}${sessions.length?sessions.slice(0,3).map(s=>`<div class="list-row"><div class="list-main"><strong>${esc(areaName(s.areaId))} · ${esc(s.topic)}</strong><small>${esc(s.learned||s.notes||'Sesión guardada')} · ${s.minutes?`${s.minutes} min`:''}</small></div></div>`).join(''):empty('Todavía no hay sesiones','Registra una sesión cuando te venga bien.')}</section><section class="card">${section('Experiencias de hoy','Extras sin obligación ni rachas.',`<button class="link-button" data-action="new-extra">Añadir →</button>`)}${extras.length?extras.slice(0,3).map(x=>`<div class="list-row"><div class="list-main"><strong>${esc(x.name)}</strong><small>${esc(x.category||'Sin categoría')} · ${esc(x.notes||x.learned||'')}</small></div></div>`).join(''):empty('Ningún extra hoy','No pasa nada si hoy no registras una actividad.')}</section></div>`}

function renderHabits(){const filter=new URLSearchParams(location.hash.split('?')[1]||'').get('archived')==='1';const items=state.habits.filter(h=>filter?h.archived:!h.archived);const todayPlan=plannedForDay(today());return `${pageHead('TU SISTEMA FLEXIBLE','Hábitos','Rutinas adaptables: diarios, en días concretos o con un objetivo semanal.',`<button class="btn" data-action="new-habit">＋ Nuevo hábito</button>`)}<div class="tabs"><button class="tab ${!filter?'active':''}" data-action="habit-filter" data-filter="active">Activos (${state.habits.filter(h=>!h.archived).length})</button><button class="tab ${filter?'active':''}" data-action="habit-filter" data-filter="archived">Archivados (${state.habits.filter(h=>h.archived).length})</button></div><div class="grid two"><section class="card">${section(filter?'Hábitos archivados':'Hábitos actuales',`${todayPlan.length} previstos hoy · pausados y archivados no cuentan.`)}${items.length?items.map(h=>habitManagementRow(h,filter)).join(''):empty(filter?'Aún no hay hábitos archivados':'Empieza con algo pequeño','Puedes crear un hábito o retomarlo cuando quieras.')}</section><aside class="stack"><section class="card">${section('Una idea sencilla','Los datos opcionales nunca son obligatorios.') }<p class="helper-text">Completar un hábito no requiere añadir minutos, cantidades ni comentarios. Puedes modificar la frecuencia, pausarlo o archivarlo en cualquier momento.</p></section><section class="card">${section('Esta semana','Progreso de hábitos semanales.')}${state.habits.filter(h=>h.frequency==='weekly'&&!h.archived&&!h.paused).length?state.habits.filter(h=>h.frequency==='weekly'&&!h.archived&&!h.paused).map(h=>`<div class="list-row"><div class="list-main"><strong>${esc(h.name)}</strong><small>${weekDone(h)} de ${Number(h.weeklyTarget)||3} sesiones</small></div><span class="tag good">${Math.min(100,Math.round(weekDone(h)/(Number(h.weeklyTarget)||3)*100))}%</span></div>`).join(''):empty('Sin objetivos semanales','Puedes programar un hábito, por ejemplo, tres veces por semana.')}</section></aside></div>`}
function habitManagementRow(h,archived){const label=h.frequency==='daily'?'Diario':h.frequency==='weekly'?`${h.weeklyTarget||3} veces / semana`:daysText(h.days);return `<div class="list-row"><div class="list-main"><strong>${esc(h.name)} ${h.paused?'<span class="tag warn">En pausa</span>':''}</strong><small>${esc(h.description||'Sin descripción')} · ${label} · Desde ${fmtShort(h.startDate)}</small></div><div class="list-actions">${!archived?`<button class="icon-button" data-action="pause-habit" data-id="${h.id}" title="${h.paused?'Reanudar':'Pausar'}">${h.paused?'▶':'Ⅱ'}</button>`:''}<button class="icon-button" data-action="edit-habit" data-id="${h.id}" title="Editar">✎</button><button class="icon-button" data-action="archive-habit" data-id="${h.id}" title="${archived?'Recuperar':'Archivar'}">${archived?'↶':'▣'}</button><button class="icon-button" data-action="delete-habit" data-id="${h.id}" title="Eliminar">×</button></div></div>`}
function daysText(days=[]){return days.length?days.map(d=>['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][d]).join(', '):'Días personalizados'}
function habitForm(h={}){const isEdit=Boolean(h.id);openDialog(isEdit?'Editar hábito':'Crear un hábito',`<form data-form="habit" data-id="${h.id||''}"><div class="form-grid">${field('Nombre','name',h.name||'')}${field('Objetivo (opcional)','target',h.target||'')}${selectField('Frecuencia','frequency',[['daily','Diaria'],['specific','Días concretos'],['weekly','Objetivo semanal']],h.frequency||'daily')}<div class="form-field wide" data-days-field><label>Días de la semana</label><div class="pill-row">${[['1','Lun'],['2','Mar'],['3','Mié'],['4','Jue'],['5','Vie'],['6','Sáb'],['0','Dom']].map(([v,t])=>`<label class="pill"><input type="checkbox" name="days" value="${v}" ${(h.days||[]).includes(Number(v))?'checked':''}> ${t}</label>`).join('')}</div></div><div data-weekly-field>${field('Veces por semana','weeklyTarget',h.weeklyTarget||3,'number','min="1" max="7"')}</div>${field('Fecha de inicio','startDate',h.startDate||today(),'date')}${textArea('Descripción (opcional)','description',h.description||'','Qué significa para ti este hábito.')}</div>${dialogActions('Cancelar',isEdit?'Guardar cambios':'Añadir hábito')}</form>`);syncHabitFormFields()}
function syncHabitFormFields(){const f=dialog.querySelector('[data-form=habit]');if(!f)return;const sync=()=>{f.querySelector('[data-days-field]').style.display=f.frequency.value==='specific'?'block':'none';f.querySelector('[data-weekly-field]').style.display=f.frequency.value==='weekly'?'block':'none'};f.frequency.addEventListener('change',sync);sync()}

function areaName(areaId){return state.areas.find(a=>a.id===areaId)?.name||'Área eliminada'}
function renderLearning(){const sessions=[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date));const minutes=sessions.reduce((n,s)=>n+(Number(s.minutes)||0),0);return `${pageHead('APRENDER POR CURIOSIDAD','Formación personal','Aprendizajes elegidos por ti, separados de las asignaturas del instituto.',`<button class="btn" data-action="new-session">＋ Registrar sesión</button>`)}<div class="grid three"><div class="card metric"><span class="metric-label">SESIONES</span><strong>${sessions.length}</strong><small>En todo el historial</small></div><div class="card metric"><span class="metric-label">TIEMPO REGISTRADO</span><strong>${durationLabel(minutes)}</strong><small>Solo sesiones con tiempo anotado</small></div><div class="card metric"><span class="metric-label">ÁREAS ACTIVAS</span><strong>${state.areas.length}</strong><small>Sin convertirlas en hábitos</small></div></div><section class="section">${section('Tus áreas de aprendizaje','Añade otras áreas, temas o intereses cuando quieras.',`<button class="btn soft small" data-action="new-area">＋ Nueva área</button>`)}<div class="grid three">${state.areas.map(a=>{const list=sessions.filter(s=>s.areaId===a.id),mins=list.reduce((n,s)=>n+(Number(s.minutes)||0),0);return `<article class="card"><div class="section-head"><span class="tag good">${esc(areaType(a.kind))}</span><div class="list-actions"><button class="icon-button" data-action="edit-area" data-id="${a.id}" title="Editar">✎</button><button class="icon-button" data-action="delete-area" data-id="${a.id}" title="Eliminar">×</button></div></div><h3 class="card-title">${esc(a.name)}</h3><p class="card-sub">${list.length} sesiones · ${durationLabel(mins)} ${mins?'registrados':''}</p><div class="pill-row" style="margin-top:14px">${(a.topics||[]).slice(0,6).map(t=>`<span class="pill" style="cursor:default">${esc(t)}</span>`).join('')}</div><button class="btn soft small" style="margin-top:16px" data-action="new-session" data-area="${a.id}">Registrar aprendizaje</button></article>`}).join('')||`<div class="card">${empty('Añade un área','Matemáticas, inglés, programación o algo nuevo.',`<button class="btn small" data-action="new-area">Nueva área</button>`)}</div>`}</div></section><section class="card section">${section('Historial de sesiones','Se puede editar y completar más tarde.')}${sessions.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Área</th><th>Contenido</th><th>Tiempo</th><th></th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${fmtShort(s.date)}</td><td>${esc(areaName(s.areaId))}</td><td>${esc(s.topic)}</td><td>${s.minutes?`${s.minutes} min`:'—'}</td><td><button class="link-button" data-action="edit-session" data-id="${s.id}">Editar</button><button class="link-button warning" data-action="delete-session" data-id="${s.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay sesiones','Puedes registrar una sesión ahora o cuando te apetezca.')}</section>`}
function areaType(k){return ({math:'Matemáticas',english:'Inglés',python:'Programación'})[k]||'Área personal'}
function durationLabel(n){if(!n)return '0 min';const h=Math.floor(n/60),m=n%60;return h?`${h} h${m?` ${m} min`:''}`:`${m} min`}
function areaForm(a={}){const isEdit=Boolean(a.id);openDialog(isEdit?'Editar área':'Nueva área de formación',`<form data-form="area" data-id="${a.id||''}"><div class="form-grid">${field('Nombre del área','name',a.name||'')}${selectField('Tipo','kind',[['general','General'],['math','Matemáticas personales'],['english','Inglés personal'],['python','Programación']],a.kind||'general')}${textArea('Temas (opcional)','topics',(a.topics||[]).join(', '),'Separa los temas con comas')}</div>${dialogActions('Cancelar',isEdit?'Guardar':'Crear área')}</form>`)}
function sessionForm(s={}){const isEdit=Boolean(s.id);const options=state.areas.map(a=>[a.id,a.name]);openDialog(isEdit?'Editar sesión':'Registrar aprendizaje',`<form data-form="session" data-id="${s.id||''}"><div class="form-grid">${selectField('Área','areaId',options,s.areaId||options[0]?.[0]||'')}${field('Fecha','date',s.date||focusDate,'date')}${field('Qué trabajaste','topic',s.topic||'')}${field('Tiempo (minutos, opcional)','minutes',s.minutes||'','number','min="0"')}${field('Qué aprendiste (opcional)','learned',s.learned||'')}${field('Dificultad (opcional)','difficulty',s.difficulty||'')}${textArea('Comentarios (opcional)','notes',s.notes||'')}</div>${dialogActions('Cancelar',isEdit?'Guardar cambios':'Guardar sesión')}</form>`)}

function renderAcademics(){const grades=[...state.grades].sort((a,b)=>b.date.localeCompare(a.date));const subjects=state.subjects;const overall=average(grades);const exams=grades.filter(g=>g.type==='exam'),terms=grades.filter(g=>g.type==='term');const bestGrade=grades.length?Math.max(...grades.map(g=>normalize(g.score,g.max))):null;const worstGrade=grades.length?Math.min(...grades.map(g=>normalize(g.score,g.max))):null;return `${pageHead('2.º DE BACHILLERATO','Notas académicas','Solo notas reales de exámenes y evaluaciones; nunca se mezclan con formación personal.',`<button class="btn" data-action="new-grade">＋ Añadir nota</button>`)}<div class="grid three"><div class="card metric"><span class="metric-label">MEDIA GENERAL</span><strong>${overall==null?'—':overall.toFixed(2)}</strong><small>${grades.length?`${grades.length} notas · normalizadas sobre 10`:'Se calculará cuando registres notas'}</small></div><div class="card metric"><span class="metric-label">EXÁMENES</span><strong>${grades.filter(g=>g.type==='exam').length}</strong><small>Notas que has registrado</small></div><div class="card metric"><span class="metric-label">ASIGNATURAS</span><strong>${subjects.length}</strong><small>Con medias independientes</small></div></div><div class="grid four section"><div class="card metric"><span class="metric-label">MEDIA DE EXÁMENES</span><strong>${average(exams)==null?'—':average(exams).toFixed(2)}</strong><small>${exams.length} registradas · sobre 10</small></div><div class="card metric"><span class="metric-label">MEDIA TRIMESTRAL</span><strong>${average(terms)==null?'—':average(terms).toFixed(2)}</strong><small>${terms.length} registradas · sobre 10</small></div><div class="card metric"><span class="metric-label">MEJOR NOTA</span><strong>${bestGrade==null?'—':bestGrade.toFixed(2)}</strong><small>Normalizada sobre 10</small></div><div class="card metric"><span class="metric-label">NOTA MÁS BAJA</span><strong>${worstGrade==null?'—':worstGrade.toFixed(2)}</strong><small>Normalizada sobre 10</small></div></div><section class="section">${section('Asignaturas','Cada asignatura conserva su propio historial.',`<button class="btn soft small" data-action="new-subject">＋ Añadir asignatura</button>`)}<div class="grid three">${subjects.map(s=>{const list=grades.filter(g=>g.subjectId===s.id);const avg=average(list);const best=list.length?Math.max(...list.map(g=>normalize(g.score,g.max))):null;return `<article class="card"><div class="section-head"><span class="tag">${esc(s.name)}</span><div class="list-actions"><button class="icon-button" data-action="edit-subject" data-id="${s.id}" title="Renombrar">✎</button><button class="icon-button" data-action="delete-subject" data-id="${s.id}" title="Eliminar asignatura">×</button></div></div><strong style="font:700 27px Manrope;color:#425743">${avg==null?'—':avg.toFixed(2)}</strong><p class="card-sub">Media sobre 10 · ${list.length} ${list.length===1?'nota':'notas'}${best==null?'':` · mejor ${best.toFixed(2)}`}</p>${list.length?gradeMiniChart(list):`<div class="empty" style="padding:14px 4px">Sin notas todavía. No se rellenan ceros.</div>`}<button class="btn soft small" data-action="new-grade" data-subject="${s.id}">Añadir nota</button></article>`}).join('')}</div></section><section class="card section">${section('Todas las notas','Las escalas distintas se convierten a una escala de 10.')}${grades.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Asignatura</th><th>Tipo</th><th>Nota</th><th>Sobre 10</th><th>Comentario</th><th></th></tr></thead><tbody>${grades.map(g=>{const s=subjects.find(x=>x.id===g.subjectId);return `<tr><td>${fmtShort(g.date)}</td><td>${esc(s?.name||'Asignatura eliminada')}</td><td>${g.type==='exam'?'Examen':`Evaluación ${esc(g.term||'trimestral')}`}</td><td>${g.score}/${g.max}</td><td>${normalize(g.score,g.max).toFixed(2)}</td><td>${esc(g.comment||'—')}</td><td><button class="link-button" data-action="edit-grade" data-id="${g.id}">Editar</button><button class="link-button warning" data-action="delete-grade" data-id="${g.id}">Eliminar</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Aún no has registrado notas','Las medias aparecerán cuando añadas resultados reales.')}</section>`}
function normalize(score,max){return max?Number(score)*10/Number(max):0}
function average(list){return list.length?list.reduce((n,g)=>n+normalize(g.score,g.max),0)/list.length:null}
function gradeMiniChart(list){const last=[...list].sort((a,b)=>a.date.localeCompare(b.date)).slice(-8);return `<div class="bar-chart" style="height:80px;padding-bottom:0">${last.map(g=>`<div class="bar-col"><div class="bar" title="${normalize(g.score,g.max).toFixed(1)} / 10" style="height:${Math.max(4,normalize(g.score,g.max)*5)}px"></div><span class="bar-label">${fmtShort(g.date).split(' ')[0]}</span></div>`).join('')}</div>`}
function subjectForm(s={}){const edit=Boolean(s.id);openDialog(edit?'Editar asignatura':'Nueva asignatura',`<form data-form="subject" data-id="${s.id||''}"><div class="form-grid">${field('Nombre','name',s.name||'')}</div>${dialogActions('Cancelar',edit?'Guardar':'Añadir asignatura')}</form>`)}
function gradeForm(g={}){const edit=Boolean(g.id);openDialog(edit?'Editar nota':'Registrar nota',`<form data-form="grade" data-id="${g.id||''}"><div class="form-grid">${selectField('Asignatura','subjectId',state.subjects.map(s=>[s.id,s.name]),g.subjectId||state.subjects[0]?.id||'')}${selectField('Tipo','type',[['exam','Examen'],['term','Evaluación trimestral']],g.type||'exam')}${field('Fecha','date',g.date||focusDate,'date')}${field('Nota obtenida','score',g.score??'','number','min="0" step="any" required')}${field('Nota máxima','max',g.max??10,'number','min="0.01" step="any" required')}${selectField('Trimestre','term',[['1.º','1.º'],['2.º','2.º'],['3.º','3.º']],g.term||'1.º')}${textArea('Comentario (opcional)','comment',g.comment||'')}</div><p class="form-hint">La nota se normalizará automáticamente sobre 10 para las medias.</p>${dialogActions('Cancelar',edit?'Guardar cambios':'Guardar nota')}</form>`);const form=dialog.querySelector('[data-form=grade]');form.type.addEventListener('change',()=>{form.querySelector('[name=term]').closest('.form-field').style.display=form.type.value==='term'?'block':'none'});form.type.dispatchEvent(new Event('change'))}

function renderExtras(){const list=[...state.extras].sort((a,b)=>b.date.localeCompare(a.date));const minutes=list.reduce((n,x)=>n+(Number(x.minutes)||0),0);const cats=state.extraCategories.map(c=>[c,list.filter(x=>x.category===c).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]);return `${pageHead('MOMENTOS QUE QUIERES RECORDAR','Extras y experiencias','Actividades puntuales que no se convierten en hábitos, rachas ni obligaciones.',`<button class="btn" data-action="new-extra">＋ Añadir experiencia</button>`)}<div class="grid three"><div class="card metric"><span class="metric-label">EXPERIENCIAS</span><strong>${list.length}</strong><small>Registros guardados</small></div><div class="card metric"><span class="metric-label">TIEMPO REGISTRADO</span><strong>${durationLabel(minutes)}</strong><small>Solo cuando añadiste duración</small></div><div class="card metric"><span class="metric-label">CATEGORÍA FAVORITA</span><strong style="font-size:17px">${cats[0]?esc(cats[0][0]):'—'}</strong><small>${cats[0]?`${cats[0][1]} registros`:'Aún no hay categorías'}</small></div></div><section class="card section">${section('Tu historial de experiencias','Se pueden editar o eliminar en cualquier momento.')}${list.length?list.map(x=>`<div class="list-row"><div class="list-main"><strong>${esc(x.name)} <span class="tag">${esc(x.category||'Sin categoría')}</span></strong><small>${fmtDate(x.date,{day:'numeric',month:'long',year:'numeric'})}${x.minutes?` · ${x.minutes} min`:''}${x.notes?` · ${esc(x.notes)}`:''}${x.learned?` · Aprendí: ${esc(x.learned)}`:''}</small></div><div class="list-actions"><button class="icon-button" data-action="edit-extra" data-id="${x.id}" title="Editar">✎</button><button class="icon-button" data-action="delete-extra" data-id="${x.id}" title="Eliminar">×</button></div></div>`).join(''):empty('Cuando quieras, guarda una experiencia','Una excursión, una receta, una charla o algo nuevo que hayas probado.')}</section><section class="card section">${section('Categorías','Solo sirven para ordenar tus experiencias.',`<button class="link-button" data-action="manage-categories">Editar categorías →</button>`)}<div class="pill-row">${state.extraCategories.map(c=>`<span class="pill" style="cursor:default">${esc(c)} · ${list.filter(x=>x.category===c).length}</span>`).join('')}</div></section>`}
function extraForm(x={}){const edit=Boolean(x.id);const cats=[...state.extraCategories];if(x.category&&!cats.includes(x.category))cats.push(x.category);openDialog(edit?'Editar experiencia':'Añadir experiencia',`<form data-form="extra" data-id="${x.id||''}"><div class="form-grid">${field('Actividad','name',x.name||'')}${field('Fecha','date',x.date||focusDate,'date')}${selectField('Categoría (opcional)','category',[['','Sin categoría'],...cats.map(c=>[c,c])],x.category||'')}${field('Duración en minutos (opcional)','minutes',x.minutes||'','number','min="0"')}${textArea('Descripción o comentario (opcional)','notes',x.notes||'')}${textArea('Qué aprendiste o cómo fue (opcional)','learned',x.learned||'')}</div>${dialogActions('Cancelar',edit?'Guardar cambios':'Guardar experiencia')}</form>`)}
function renderGoals(){const counts={pending:0,progress:0,done:0,abandoned:0};state.goals.forEach(g=>counts[g.status]=(counts[g.status]||0)+1);return `${pageHead('MÁS ADELANTE','Objetivos','Metas personales a largo plazo, independientes de tus hábitos diarios.',`<button class="btn" data-action="new-goal">＋ Nuevo objetivo</button>`)}<div class="grid four">${[['EN PROGRESO',counts.progress,'◎'],['PENDIENTES',counts.pending,'◷'],['CONSEGUIDOS',counts.done,'✓'],['APARCADOS',counts.abandoned,'—']].map(([l,n,i])=>`<div class="card metric"><span class="metric-icon">${i}</span><span class="metric-label">${l}</span><strong>${n}</strong></div>`).join('')}</div><section class="section">${section('Tus objetivos','Actualiza el estado o añade notas cuando avances.')}${state.goals.length?`<div class="grid two">${state.goals.map(g=>`<article class="card"><div class="section-head"><span class="tag ${g.status==='done'?'good':''}">${goalStatus(g.status)}</span><div class="list-actions"><button class="icon-button" data-action="edit-goal" data-id="${g.id}" title="Editar">✎</button><button class="icon-button" data-action="delete-goal" data-id="${g.id}" title="Eliminar">×</button></div></div><h3 class="card-title">${esc(g.name)}</h3><p class="card-sub">${esc(g.description||'Sin descripción')}${g.targetDate?` · Objetivo: ${fmtShort(g.targetDate)}`:''}</p>${g.progress?`<div class="progress-track" style="margin:15px 0 8px"><span style="width:${Math.max(0,Math.min(100,Number(g.progress)))}%"></span></div><small class="muted">${Number(g.progress)}% de progreso</small>`:''}${(g.relatedHabitIds||[]).length||(g.relatedAreaIds||[]).length?`<div class="pill-row" style="margin-top:13px">${(g.relatedHabitIds||[]).map(hid=>`<span class="pill" style="cursor:default">✓ ${esc(state.habits.find(h=>h.id===hid)?.name||'Hábito')}</span>`).join('')}${(g.relatedAreaIds||[]).map(aid=>`<span class="pill" style="cursor:default">⌘ ${esc(areaName(aid))}</span>`).join('')}</div>`:''}${g.note?`<div class="divider"></div><p class="helper-text">${esc(g.note)}</p>`:''}</article>`).join('')}</div>`:empty('Aún no hay objetivos','Puedes empezar con una idea grande o un paso pequeño.',`<button class="btn small" data-action="new-goal">Añadir un objetivo</button>`)}</section>`}
function goalStatus(s){return ({pending:'Pendiente',progress:'En progreso',done:'Conseguido',abandoned:'Abandonado'})[s]||'Pendiente'}
function goalForm(g={}){const edit=Boolean(g.id);const active=state.habits.filter(h=>!h.archived);openDialog(edit?'Editar objetivo':'Nuevo objetivo',`<form data-form="goal" data-id="${g.id||''}"><div class="form-grid">${field('Nombre','name',g.name||'')}${selectField('Estado','status',[['pending','Pendiente'],['progress','En progreso'],['done','Conseguido'],['abandoned','Abandonado']],g.status||'pending')}${field('Fecha objetivo (opcional)','targetDate',g.targetDate||'','date')}${field('Progreso % (opcional)','progress',g.progress||'','number','min="0" max="100"')}${textArea('Descripción (opcional)','description',g.description||'')}${textArea('Nota o actualización (opcional)','note',g.note||'')}<div class="form-field wide"><label>Hábitos relacionados (opcional)</label><div class="pill-row">${active.map(h=>`<label class="pill"><input type="checkbox" name="relatedHabitIds" value="${h.id}" ${(g.relatedHabitIds||[]).includes(h.id)?'checked':''}> ${esc(h.name)}</label>`).join('')||'<span class="helper-text">No hay hábitos activos.</span>'}</div></div><div class="form-field wide"><label>Áreas de formación relacionadas (opcional)</label><div class="pill-row">${state.areas.map(a=>`<label class="pill"><input type="checkbox" name="relatedAreaIds" value="${a.id}" ${(g.relatedAreaIds||[]).includes(a.id)?'checked':''}> ${esc(a.name)}</label>`).join('')||'<span class="helper-text">No hay áreas creadas.</span>'}</div></div></div>${dialogActions('Cancelar',edit?'Guardar cambios':'Crear objetivo')}</form>`)}

function renderCalendar(){const yr=calendarMonth.getFullYear(),mo=calendarMonth.getMonth();const first=new Date(yr,mo,1,12),last=new Date(yr,mo+1,0,12);const offset=(first.getDay()+6)%7;const cells=[];for(let i=0;i<offset;i++)cells.push(null);for(let d=1;d<=last.getDate();d++)cells.push(new Date(yr,mo,d,12));while(cells.length%7)cells.push(null);const items=dayItems(focusDate);return `${pageHead('TU HISTORIAL','Calendario','Los días vacíos son días sin datos, no días incumplidos.',`<div class="actions-row"><button class="btn soft small" data-action="new-extra">＋ Experiencia</button><button class="btn soft small" data-action="new-session">＋ Aprendizaje</button></div>`)}<section class="card"><div class="calendar-head"><div class="month-nav"><button data-action="month-shift" data-delta="-1">‹</button><strong>${calendarMonth.toLocaleDateString('es-ES',{month:'long',year:'numeric'})}</strong><button data-action="month-shift" data-delta="1">›</button></div><button class="btn line small" data-action="calendar-today">Hoy</button></div><div class="calendar-grid">${['L','M','X','J','V','S','D'].map(d=>`<div class="calendar-dow">${d}</div>`).join('')}${cells.map(d=>{if(!d)return '<div></div>';const k=dateKey(d),cls=[k===focusDate?'selected':'',k===today()?'today':'',d.getMonth()!==mo?'muted':''].join(' ');return `<button class="calendar-day ${cls}" data-action="select-date" data-date="${k}"><span class="day-number">${d.getDate()}</span>${activityOn(k)?'<span class="day-dot"></span>':''}</button>`}).join('')}</div></section><section class="card day-detail">${section(fmtDate(focusDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'}),'Actividad registrada para esta fecha.',`<button class="link-button" data-action="edit-reflection" data-date="${focusDate}">Ánimo y reflexión →</button>`)}${items.length?items.map(x=>`<div class="list-row"><div class="list-main"><strong><span class="tag">${esc(x.type)}</span> ${esc(x.title)}</strong><small>${esc(x.detail||'')}</small></div>${x.edit?`<button class="link-button" data-action="${x.edit}" data-id="${x.id}">Editar</button>`:''}</div>`).join(''):empty('Sin registros','Este día aparece vacío porque no se guardó actividad.')}${state.moods[focusDate]?`<div class="divider"></div><p class="helper-text">Ánimo: ${['','Muy mal','Mal','Normal','Bien','Muy bien'][state.moods[focusDate]]}</p>`:''}${state.reflections[focusDate]?`<p class="helper-text">${esc(state.reflections[focusDate])}</p>`:''}</section>`}
function dayItems(date){const list=[];const dailyPlan=plannedForDay(date);const planIds=new Set(dailyPlan.map(h=>h.id));const loggedIds=new Set(Object.keys(state.habitEntries[date]||{}));for(const h of state.habits.filter(x=>planIds.has(x.id)||loggedIds.has(x.id))){const e=entryFor(date,h.id);if(e?.status==='done'||e?.status==='excluded'||e?.status==='missed')list.push({type:e.status==='done'?'Hábito completado':e.status==='excluded'?'Excluido':'No realizado',title:h.name,detail:e.note||e.minutes?`${e.note||''}${e.minutes?` · ${e.minutes} min`:''}`:h.description});else if(planIds.has(h.id)&&date>=today())list.push({type:'Pendiente',title:h.name,detail:h.description||'Sin registro todavía'})}for(const h of state.habits.filter(x=>x.frequency==='weekly'&&!x.archived&&!x.paused)){const e=entryFor(date,h.id);if(e?.status==='done')list.push({type:'Sesión de hábito semanal',title:h.name,detail:e.minutes?`${e.minutes} min`:e.note||'Sesión registrada'})}state.sessions.filter(x=>x.date===date).forEach(x=>list.push({type:'Formación personal',title:`${areaName(x.areaId)} · ${x.topic}`,detail:x.learned||x.notes||`${x.minutes||''} min`,id:x.id,edit:'edit-session'}));state.extras.filter(x=>x.date===date).forEach(x=>list.push({type:'Extra',title:x.name,detail:[x.category,x.minutes?`${x.minutes} min`:'',x.notes,x.learned].filter(Boolean).join(' · '),id:x.id,edit:'edit-extra'}));state.grades.filter(x=>x.date===date).forEach(x=>list.push({type:'Nota académica',title:`${state.subjects.find(s=>s.id===x.subjectId)?.name||'Asignatura'} · ${x.score}/${x.max}`,detail:x.type==='exam'?'Examen':`Evaluación ${x.term}`}));return list}

function dateRange(){const end=today();if(statsRange==='custom')return statsCustom;if(statsRange==='all')return {from:state.settings.startDate||end,to:end};const n=Number(statsRange);return {from:dateKey(new Date(parseDate(end).getTime()-Math.max(0,n-1)*86400000)),to:end}}
function renderStatistics(){const range=dateRange();const dates=Object.keys(state.habitEntries).filter(d=>d>=range.from&&d<=range.to).sort();let done=0,logged=0,excluded=0;dates.forEach(d=>Object.values(state.habitEntries[d]||{}).forEach(e=>{if(e.status==='done'){done++;logged++}else if(e.status==='missed')logged++;else if(e.status==='excluded')excluded++}));const compliance=logged?Math.round(done/logged*100):null;const runs=streakStats(range);const periods=weeklyStats(range);const sessions=state.sessions.filter(s=>s.date>=range.from&&s.date<=range.to);const extras=state.extras.filter(s=>s.date>=range.from&&s.date<=range.to);const grades=state.grades.filter(s=>s.date>=range.from&&s.date<=range.to);const moods=Object.entries(state.moods).filter(([d])=>d>=range.from&&d<=range.to);return `${pageHead('VER TU EVOLUCIÓN','Estadísticas','Cifras basadas en registros guardados. Los días sin datos quedan fuera.',`<div class="date-pill">${fmtShort(range.from)} — ${fmtShort(range.to)}</div>`)}<div class="toolbar"><div class="tabs" style="margin:0">${[['7','7 días'],['30','30 días'],['90','90 días'],['365','365 días'],['all','Todo'],['custom','Personalizado']].map(([v,l])=>`<button class="tab ${statsRange===v?'active':''}" data-action="stats-range" data-range="${v}">${l}</button>`).join('')}</div>${statsRange==='custom'?`<div class="actions-row"><input class="field inline-input" type="date" id="custom-from" value="${range.from}"><input class="field inline-input" type="date" id="custom-to" value="${range.to}"><button class="btn soft small" data-action="apply-custom">Aplicar</button></div>`:''}</div><div class="grid four"><div class="card metric"><span class="metric-label">HÁBITOS REGISTRADOS</span><strong>${compliance==null?'—':`${compliance}%`}</strong><small>${logged} registros evaluables · ${excluded} exclusiones ignoradas</small></div><div class="card metric"><span class="metric-label">SESIONES DE APRENDIZAJE</span><strong>${sessions.length}</strong><small>${durationLabel(sessions.reduce((n,s)=>n+(Number(s.minutes)||0),0))} registrados</small></div><div class="card metric"><span class="metric-label">EXPERIENCIAS</span><strong>${extras.length}</strong><small>${durationLabel(extras.reduce((n,s)=>n+(Number(s.minutes)||0),0))} registrados</small></div><div class="card metric"><span class="metric-label">NOTAS</span><strong>${grades.length}</strong><small>${grades.length?`Media ${average(grades).toFixed(2)} / 10`:'Sin notas en este periodo'}</small></div></div><div class="grid four section"><div class="card metric"><span class="metric-label">DÍAS PERFECTOS REGISTRADOS</span><strong>${runs.perfect}</strong><small>Con todos los hábitos previstos hechos o excluidos</small></div><div class="card metric"><span class="metric-label">RACHA ACTUAL</span><strong>${runs.current}</strong><small>Días perfectos con registro</small></div><div class="card metric"><span class="metric-label">MEJOR RACHA</span><strong>${runs.best}</strong><small>Días perfectos registrados</small></div><div class="card metric"><span class="metric-label">HÁBITOS COMPLETADOS</span><strong>${done}</strong><small>En el periodo seleccionado</small></div></div><div class="grid two section"><section class="card">${section('Evolución semanal','Porcentaje solo de registros completados o marcados como no realizados.')}${periods.some(x=>x.total)?`<div class="bar-chart">${periods.map(p=>`<div class="bar-col"><span class="bar-value">${p.total?`${p.value}%`:''}</span><div class="bar ${p.current?'current':''}" style="height:${p.total?Math.max(4,p.value*1.1):3}px"></div><span class="bar-label">${p.label}</span></div>`).join('')}</div>`:empty('Aún faltan registros','Cuando guardes actividad, verás aquí la evolución.')}</section><section class="card">${section('Hábitos más constantes','Según los días registrados en el periodo.')}${habitStats(range).length?habitStats(range).slice(0,6).map(h=>`<div class="list-row"><div class="list-main"><strong>${esc(h.name)}</strong><small>${h.done} completados de ${h.total} registrados</small></div><span class="tag good">${h.total?Math.round(h.done/h.total*100):0}%</span></div>`).join(''):empty('Sin datos de hábitos','Los días no registrados no se cuentan como fallos.')}</section></div><div class="grid two section"><section class="card">${section('Estado de ánimo','Descriptivo; no es un diagnóstico.')}${moods.length?`<div class="pill-row">${[1,2,3,4,5].map(n=>{const c=moods.filter(([,v])=>v===n).length;return `<span class="pill" style="cursor:default">${['','☹️','🙁','😐','🙂','😊'][n]} ${['','Muy mal','Mal','Normal','Bien','Muy bien'][n]} · ${c}</span>`}).join('')}</div><p class="footer-note">Estos datos no permiten afirmar que una cosa cause otra.</p>`:empty('Sin valoraciones','El estado de ánimo es completamente opcional.')}</section><section class="card">${section('Aprendizaje por área','Solo sesiones de formación personal.')}${areaStats(range).length?areaStats(range).map(a=>`<div class="list-row"><div class="list-main"><strong>${esc(a.name)}</strong><small>${a.count} sesiones · ${durationLabel(a.minutes)}</small></div></div>`).join(''):empty('Sin sesiones','Cuando registres aprendizajes aparecerán aquí.')}</section></div>`}
function streakStats(range){const days=Object.keys(state.habitEntries).filter(d=>d>=range.from&&d<=range.to&&d<=today()).sort();const records=[];for(const d of days){const plan=plannedForDay(d);if(!plan.length)continue;const statuses=plan.map(h=>entryFor(d,h.id)?.status);records.push({date:d,perfect:statuses.every(x=>x==='done'||x==='excluded')&&statuses.includes('done')})}let best=0,current=0,run=0;for(const day of records){if(day.perfect){run++;best=Math.max(best,run)}else run=0}for(let i=records.length-1;i>=0&&records[i].perfect;i--)current++;return {perfect:records.filter(x=>x.perfect).length,current,best}}
function weeklyStats(range){const out=[];const start=parseDate(range.from);const end=parseDate(range.to);let d=new Date(start);while(d<=end){const weekStart=new Date(d);weekStart.setDate(d.getDate()-((d.getDay()+6)%7));const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);const a=dateKey(weekStart),b=dateKey(weekEnd);let dn=0,total=0;Object.entries(state.habitEntries).forEach(([key,entries])=>{if(key>=a&&key<=b&&key>=range.from&&key<=range.to)Object.values(entries||{}).forEach(e=>{if(e.status==='done'){dn++;total++}else if(e.status==='missed')total++})});out.push({label:weekStart.toLocaleDateString('es-ES',{day:'numeric',month:'short'}),value:total?Math.round(dn/total*100):0,total,current:b>=today()&&a<=today()});d.setDate(weekEnd.getDate()+1)}return out.slice(-12)}
function habitStats(range){return state.habits.map(h=>{let done=0,total=0;Object.entries(state.habitEntries).forEach(([d,entries])=>{const e=entries?.[h.id];if(d>=range.from&&d<=range.to&&e){if(e.status==='done'){done++;total++}else if(e.status==='missed')total++}});return {name:h.name,done,total}}).filter(x=>x.total).sort((a,b)=>b.done/b.total-a.done/a.total)}
function areaStats(range){return state.areas.map(a=>{const ss=state.sessions.filter(s=>s.areaId===a.id&&s.date>=range.from&&s.date<=range.to);return {name:a.name,count:ss.length,minutes:ss.reduce((n,s)=>n+(Number(s.minutes)||0),0)}}).filter(x=>x.count).sort((a,b)=>b.count-a.count)}

function renderSettings(){return `${pageHead('TUS PREFERENCIAS','Configuración','Controla tus áreas, asignaturas, categorías y copias de seguridad.')}<div class="grid two"><div class="stack"><section class="card">${section('Áreas de formación','Contenido personal, separado de Bachillerato.',`<button class="link-button" data-view="learning">Gestionar →</button>`)}<p class="helper-text">${state.areas.map(a=>esc(a.name)).join(' · ')||'Sin áreas'}</p></section><section class="card">${section('Asignaturas','Solo notas oficiales.',`<button class="link-button" data-view="academics">Gestionar →</button>`)}<p class="helper-text">${state.subjects.map(s=>esc(s.name)).join(' · ')||'Sin asignaturas'}</p></section><section class="card">${section('Categorías de extras','Etiquetas libres, sin efecto en tus hábitos.',`<button class="link-button" data-action="manage-categories">Editar →</button>`)}<div class="pill-row">${state.extraCategories.map(c=>`<span class="pill" style="cursor:default">${esc(c)}</span>`).join('')}</div></section><section class="card">${section('iCloud y sincronización')}<div class="callout"><strong>Esta versión no sincroniza automáticamente entre dispositivos.</strong><br>Los datos se guardan en el navegador o en la app instalada en cada dispositivo. CloudKit JS puede conectar una web con iCloud, pero requiere crear un contenedor de app y configurar su acceso web y autenticación. Mientras tanto, usa exportar/importar para transferir una copia. <a href="https://developer.apple.com/documentation/cloudkitjs" target="_blank" rel="noopener">Documentación de Apple sobre CloudKit JS</a>.</div></section></div><div class="stack"><section class="card">${section('Copias de seguridad','Exporta los datos para guardarlos o moverlos a otro dispositivo.')}<div class="backup-box"><h3>Exportar todos mis datos</h3><p>Descarga un archivo JSON con hábitos, registros, notas, sesiones, extras, reflexiones, objetivos y preferencias.</p><button class="btn soft" data-action="export">↓ Descargar copia</button></div><div class="divider"></div><div class="backup-box"><h3>Importar una copia</h3><p>La importación sustituye los datos actuales del dispositivo. Haz una copia antes si quieres conservarlos.</p><label class="btn line" for="import-file">↑ Elegir archivo JSON</label><input id="import-file" type="file" accept="application/json,.json" hidden></div></section><section class="card">${section('Almacenamiento')}<p class="helper-text">Tus registros están guardados localmente en este dispositivo, sin cuenta ni servidor propio. El repositorio privado guarda el código y la especificación; no contiene ni respalda los registros de la app.</p><p class="footer-note">Último inicio del historial: ${fmtDate(state.settings.startDate,{day:'numeric',month:'long',year:'numeric'})}. Los registros empiezan cuando comienzas a usar la app.</p></section><section class="card">${section('Reiniciar datos')}<p class="helper-text">Borra los datos guardados en este dispositivo y vuelve a la configuración inicial. Esta acción no se puede deshacer desde la app.</p><button class="btn danger small" data-action="reset-data">Borrar datos locales</button></section><section class="card">${section('Acerca de 27')}<p class="helper-text">Una herramienta personal para observar tu evolución con curiosidad y sin presión. No vende tus datos y no usa cuentas, anuncios ni suscripciones.</p><span class="tag good">PWA · Offline primero</span></section></div></div>`}

function factsHistoryDialog(){openDialog('Curiosidades y favoritas',`<div class="stack">${facts.map(f=>`<div class="list-row"><div class="list-main"><strong>${esc(f.text)}</strong><small>Fuente: <a href="${f.url}" target="_blank" rel="noopener">${esc(f.source)}</a></small></div><button class="icon-button" type="button" data-action="toggle-favorite-fact" data-text="${esc(f.text)}" title="${state.favorites.includes(f.text)?'Quitar de favoritas':'Guardar en favoritas'}">${state.favorites.includes(f.text)?'♥':'♡'}</button></div>`).join('')}${state.customFacts.map(f=>`<div class="list-row"><div class="list-main"><strong>${esc(f.text)}</strong><small>${esc(f.source||'Añadida por ti')}${f.url?` · <a href="${esc(f.url)}" target="_blank" rel="noopener">Ver fuente</a>`:''}</small></div></div>`).join('')}</div>`)}

function bindLocalForms(){const note=state.reflections[focusDate]||'';const f=root.querySelector('[data-autosave-reflection]');if(f){f.value=note;f.addEventListener('input',()=>{state.reflections[focusDate]=f.value;save()})}}

// Interactions
document.addEventListener('click',e=>{
 const viewButton=e.target.closest('[data-view]');if(viewButton){setView(viewButton.dataset.view);return}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,idValue=b.dataset.id,date=b.dataset.date||focusDate;
 if(a==='close-dialog'){closeDialog();return}
 if(a==='new-habit')habitForm();
 else if(a==='edit-habit')habitForm(state.habits.find(h=>h.id===idValue)||{});
 else if(a==='pause-habit'){const h=state.habits.find(h=>h.id===idValue);h.paused=!h.paused;save();render();showToast(h.paused?'Hábito en pausa':'Hábito reanudado')}
 else if(a==='archive-habit'){const h=state.habits.find(h=>h.id===idValue);h.archived=!h.archived;h.paused=false;save();render();showToast(h.archived?'Hábito archivado':'Hábito recuperado')}
 else if(a==='delete-habit'){if(confirm('¿Eliminar este hábito y todos sus registros? Esta acción no se puede deshacer.')){state.habits=state.habits.filter(h=>h.id!==idValue);Object.keys(state.habitEntries).forEach(d=>{delete state.habitEntries[d][idValue];if(!Object.keys(state.habitEntries[d]).length)delete state.habitEntries[d]});state.goals.forEach(g=>g.relatedHabitIds=(g.relatedHabitIds||[]).filter(x=>x!==idValue));save();render();showToast('Hábito eliminado')}}
 else if(a==='habit-filter'){location.hash=a==='habit-filter'&&b.dataset.filter==='archived'?'#habits?archived=1':'#habits';setView('habits')}
 else if(a==='toggle-habit'){const h=state.habits.find(x=>x.id===idValue);const old=entryFor(date,idValue);setEntry(date,idValue,old?.status==='done'?'pending':'done',entryDetails(old));render();showToast(old?.status==='done'?'Registro actualizado':'Hábito completado')}
 else if(a==='exclude-habit'){const h=state.habits.find(x=>x.id===idValue);const old=entryFor(date,idValue);if(old?.status==='excluded')setEntry(date,idValue,'pending');else setEntry(date,idValue,'excluded');render();showToast(old?.status==='excluded'?'Día incluido de nuevo':'Hábito excluido de este día')}
 else if(a==='habit-day-detail')habitDetail(idValue,date);
 else if(a==='weekly-done'){setEntry(date,idValue,'done',{weekly:true});render();showToast('Sesión semanal registrada')}
 else if(a==='new-area')areaForm();
 else if(a==='edit-area')areaForm(state.areas.find(x=>x.id===idValue)||{});
 else if(a==='delete-area'){if(confirm('¿Eliminar esta área? Las sesiones guardadas se conservarán y seguirán en el historial.')){state.areas=state.areas.filter(x=>x.id!==idValue);save();render()}}
 else if(a==='new-session')sessionForm({areaId:b.dataset.area||''});
 else if(a==='edit-session')sessionForm(state.sessions.find(x=>x.id===idValue)||{});
 else if(a==='delete-session')removeItem('sessions',idValue,'¿Eliminar esta sesión?');
 else if(a==='new-subject')subjectForm();
 else if(a==='edit-subject')subjectForm(state.subjects.find(x=>x.id===idValue)||{});
 else if(a==='delete-subject'){if(confirm('¿Eliminar esta asignatura? Sus notas se conservarán en el historial sin asignatura.')){state.subjects=state.subjects.filter(x=>x.id!==idValue);save();render()}}
 else if(a==='new-grade')gradeForm({subjectId:b.dataset.subject||''});
 else if(a==='edit-grade')gradeForm(state.grades.find(x=>x.id===idValue)||{});
 else if(a==='delete-grade')removeItem('grades',idValue,'¿Eliminar esta nota?');
 else if(a==='new-extra')extraForm();
 else if(a==='edit-extra')extraForm(state.extras.find(x=>x.id===idValue)||{});
 else if(a==='delete-extra')removeItem('extras',idValue,'¿Eliminar esta experiencia?');
 else if(a==='manage-categories')categoryForm();
 else if(a==='new-goal')goalForm();
 else if(a==='edit-goal')goalForm(state.goals.find(x=>x.id===idValue)||{});
 else if(a==='delete-goal')removeItem('goals',idValue,'¿Eliminar este objetivo?');
 else if(a==='edit-reflection')reflectionForm(date);
 else if(a==='mood'){state.moods[focusDate]=Number(b.dataset.value);save();render()}
 else if(a==='favorite-fact'){const fact=facts[(parseDate(focusDate).getTime()/86400000|0)%facts.length];state.favorites=state.favorites.includes(fact.text)?state.favorites.filter(x=>x!==fact.text):[...state.favorites,fact.text];save();render();showToast(state.favorites.includes(fact.text)?'Guardada en favoritas':'Quitada de favoritas')}
 else if(a==='facts-history')factsHistoryDialog()
 else if(a==='toggle-favorite-fact'){const text=b.dataset.text;state.favorites=state.favorites.includes(text)?state.favorites.filter(x=>x!==text):[...state.favorites,text];save();factsHistoryDialog()}
 else if(a==='month-shift'){calendarMonth.setMonth(calendarMonth.getMonth()+Number(b.dataset.delta));render()}
 else if(a==='calendar-today'){focusDate=today();calendarMonth=new Date();render()}
 else if(a==='select-date'){focusDate=b.dataset.date;render()}
 else if(a==='stats-range'){statsRange=b.dataset.range;render()}
 else if(a==='apply-custom'){statsCustom={from:root.querySelector('#custom-from').value,to:root.querySelector('#custom-to').value};render()}
 else if(a==='export')exportData()
 else if(a==='reset-data'){if(confirm('¿Seguro que quieres borrar todos los datos locales de 27? Esta acción no se puede deshacer.')){localStorage.removeItem(KEY);state=defaults();save();setView('today');showToast('Datos reiniciados')}}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-action="toggle-habit"]')){const h=e.target.dataset.id;const old=entryFor(focusDate,h);setEntry(focusDate,h,e.target.checked?'done':'pending',entryDetails(old));render();showToast(e.target.checked?'Hábito completado':'Registro actualizado')}if(e.target.id==='import-file'&&e.target.files?.[0])importData(e.target.files[0])});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!['habit','area','session','subject','grade','extra','goal'].includes(form.dataset.form))return;const d=new FormData(form);const obj=Object.fromEntries(d.entries());const existingId=form.dataset.id;const put=(bucket,data)=>{if(existingId){const i=state[bucket].findIndex(x=>x.id===existingId);if(i>=0)state[bucket][i]={...state[bucket][i],...data}}else state[bucket].unshift({id:id(),...data})};
 if(form.dataset.form==='habit'){obj.days=[...form.querySelectorAll('[name=days]:checked')].map(x=>Number(x.value));obj.weeklyTarget=Number(obj.weeklyTarget)||3;if(!existingId){obj.paused=false;obj.archived=false}put('habits',obj)}
 if(form.dataset.form==='area'){obj.topics=(obj.topics||'').split(',').map(s=>s.trim()).filter(Boolean);put('areas',obj)}
 if(form.dataset.form==='session'){obj.minutes=obj.minutes?Number(obj.minutes):'';put('sessions',obj)}
 if(form.dataset.form==='subject')put('subjects',obj)
 if(form.dataset.form==='grade'){obj.score=Number(obj.score);obj.max=Number(obj.max)||10;put('grades',obj)}
 if(form.dataset.form==='extra'){obj.minutes=obj.minutes?Number(obj.minutes):'';put('extras',obj)}
 if(form.dataset.form==='goal'){obj.progress=obj.progress===''?'':Number(obj.progress);if(!existingId)obj.createdAt=today();obj.relatedHabitIds=[...form.querySelectorAll('[name=relatedHabitIds]:checked')].map(x=>x.value);obj.relatedAreaIds=[...form.querySelectorAll('[name=relatedAreaIds]:checked')].map(x=>x.value);put('goals',obj)}
 closeDialog();save();render();showToast('Guardado')
});
document.querySelector('#menu-toggle').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#sidebar').classList.remove('open')});

function habitDetail(habitId,date){const h=state.habits.find(x=>x.id===habitId);if(!h)return;const e=entryFor(date,habitId)||{};openDialog(`${esc(h.name)} · ${fmtShort(date)}`,`<form data-form="habit-detail" data-id="${habitId}" data-date="${date}"><div class="form-grid">${field('Tiempo en minutos (opcional)','minutes',e.minutes||'','number','min="0"')}${field('Cantidad o resultado (opcional)','value',e.value||'')}${textArea('Comentario (opcional)','note',e.note||'')}</div><div class="actions-row" style="margin-top:15px"><button class="btn soft small" type="button" data-action="mark-missed" data-id="${habitId}" data-date="${date}">Marcar no realizado</button><button class="btn line small" type="button" data-action="clear-entry" data-id="${habitId}" data-date="${date}">Borrar registro</button></div>${dialogActions('Cerrar','Guardar detalle')}</form>`)}
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form="habit-detail"]');if(!f)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));d.minutes=d.minutes?Number(d.minutes):'';setEntry(f.dataset.date,f.dataset.id,entryFor(f.dataset.date,f.dataset.id)?.status==='excluded'?'excluded':'done',d);closeDialog();render();showToast('Registro actualizado')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="mark-missed"],[data-action="clear-entry"]');if(!b)return;if(b.dataset.action==='mark-missed')setEntry(b.dataset.date,b.dataset.id,'missed');else setEntry(b.dataset.date,b.dataset.id,'pending');closeDialog();render();showToast(b.dataset.action==='mark-missed'?'Día marcado como no realizado':'Registro borrado')});
function reflectionForm(date){const mood=state.moods[date]||0;openDialog(`Ánimo y reflexión · ${fmtShort(date)}`,`<form data-form="reflection" data-date="${date}"><div class="form-field"><label>¿Cómo te ha ido?</label><div class="mood-options">${['Muy mal','Mal','Normal','Bien','Muy bien'].map((m,i)=>`<label class="mood-option ${mood===i+1?'active':''}"><input type="radio" name="mood" value="${i+1}" ${mood===i+1?'checked':''} style="display:none"><span>${['☹️','🙁','😐','🙂','😊'][i]}</span>${m}</label>`).join('')}</div></div><div class="form-field" style="margin-top:17px"><label for="reflection-text">Reflexión (opcional)</label><textarea id="reflection-text" name="text" placeholder="Puedes dejarlo en blanco.">${esc(state.reflections[date]||'')}</textarea></div>${dialogActions('Cancelar','Guardar')}</form>`)}
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form="reflection"]');if(!f)return;e.preventDefault();const data=new FormData(f);const m=data.get('mood');if(m)state.moods[f.dataset.date]=Number(m);else delete state.moods[f.dataset.date];const text=data.get('text')||'';if(text.trim())state.reflections[f.dataset.date]=text.trim();else delete state.reflections[f.dataset.date];save();closeDialog();render();showToast('Reflexión guardada')});
function categoryForm(){openDialog('Categorías de experiencias',`<form data-form="categories"><div class="form-field"><label for="cats">Una categoría por línea</label><textarea id="cats" name="categories">${esc(state.extraCategories.join('\n'))}</textarea></div><p class="form-hint">Las categorías eliminadas de esta lista no borran las actividades guardadas.</p>${dialogActions('Cancelar','Guardar categorías')}</form>`)}
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form="categories"]');if(!f)return;e.preventDefault();state.extraCategories=[...new Set(new FormData(f).get('categories').split('\n').map(s=>s.trim()).filter(Boolean))];save();closeDialog();render()});
function removeItem(bucket,itemId,message){if(confirm(message)){state[bucket]=state[bucket].filter(x=>x.id!==itemId);save();render();showToast('Eliminado')}}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`27-copia-${today()}.json`;a.click();URL.revokeObjectURL(a.href);showToast('Copia descargada')}
function importData(file){const reader=new FileReader();reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(!incoming||!Array.isArray(incoming.habits)||!Array.isArray(incoming.areas)||!incoming.settings)throw new Error('Formato no reconocido');if(!confirm('Importar sustituirá todos los datos actuales de este dispositivo. ¿Continuar?'))return;const d=defaults();state={...d,...incoming,settings:{...d.settings,...incoming.settings}};save();render();showToast('Copia importada correctamente')}catch{showToast('El archivo no es una copia válida de 27')}};reader.readAsText(file)}

document.addEventListener('change',e=>{if(e.target.matches('[data-form="reflection"] input[type=radio]')){e.target.closest('.mood-options').querySelectorAll('.mood-option').forEach(x=>x.classList.remove('active'));e.target.closest('.mood-option').classList.add('active')}});
if('serviceWorker' in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{})}
render();
